<template>
  <section class="compositionWorkspace">
    <header class="compositionHeader"><div><h2>拼页与气泡</h2><p>先选页面模板，再点画格编辑。气泡可拖动，右下角手柄调整大小。</p></div><div><button @click="emit('draw')">返回绘制</button><button class="primary" @click="emit('preview')">预览与导出 →</button></div></header>
    <div class="templateBar"><strong>页面模板</strong><button v-for="item in templates" :key="item.id" :aria-pressed="episode.layout.perPage === item.count && (episode.layout.arrangement || 'grid') === item.arrangement" @click="setTemplate(item)"><span class="miniTemplate" :class="item.id"><i v-for="n in item.count" :key="n"></i></span>{{ item.label }}</button><details><summary>字体与页面细节</summary><div class="pageOptions"><label>全篇字体<select v-model="episode.layout.fontFamily"><option value="sans">系统黑体</option><option value="wenkai">霞鹜文楷</option><option value="genkiGothic">源起黑体</option><option value="huninn">粉圆</option><option value="genkiMin">源起明体</option><option value="serif">系统宋体</option></select></label><label>默认字号<input v-model.number="episode.layout.fontSize" type="range" min="20" max="60" />{{ episode.layout.fontSize }} px</label><label>文字位置<select v-model="episode.layout.textMode"><option value="overlay">画内漫画气泡</option><option value="safe">画外留白</option></select></label><label>间距<input v-model.number="episode.layout.gutter" type="range" min="8" max="60" /></label><label>纸张底色<input v-model="episode.layout.background" type="color" /></label><label><input v-model="episode.layout.comicFlavor" type="checkbox" />纸张质感与页码</label></div></details></div>
    <div v-if="episode.panels.length" class="compositionBody">
      <nav class="pageNavigator" aria-label="排版页面"><label>当前页<select :value="pageIndex" @change="panelIndex = Number(($event.target as HTMLSelectElement).value) * episode.layout.perPage"><option v-for="n in pageCount" :key="n" :value="n-1">第 {{ n }} / {{ pageCount }} 页</option></select></label><div class="pageButtons"><button v-for="n in pageCount" :key="n" :aria-pressed="pageIndex === n-1" @click="panelIndex = (n-1)*episode.layout.perPage"><img v-if="previewUrls[n-1]" :src="previewUrls[n-1]" alt="" /><span>第 {{ n }} 页</span></button></div></nav>
      <div class="compositionCanvas"><div class="frameToolbar"><strong>第 {{ pageIndex + 1 }} 页</strong><label>编辑画格<select v-model.number="panelIndex"><option v-for="(panel,index) in episode.panels" :key="panel.id" :value="index">第 {{ index + 1 }} 格 · {{ panel.action.slice(0,16) || '未描述' }}</option></select></label><button :disabled="panelIndex === 0" @click="move(-1)">前移</button><button :disabled="panelIndex === episode.panels.length-1" @click="move(1)">后移</button><button @click="emit('remove', currentPanel!)">移除画格</button></div>
        <letteringEditor v-if="currentPanel" :panel="currentPanel" :episode="episode" :files="files" :cast="episode.castSnapshot" :textMode="episode.layout.textMode" :fontFamily="episode.layout.fontFamily" @selectPanel="panelIndex = $event" />
        <details v-if="currentPanel" class="frameNotes"><summary>本格旁白与音效</summary><label>画外旁白<textarea v-model="currentPanel.caption" rows="2" maxlength="300" /></label><label>音效字<input v-model="currentPanel.sfx" maxlength="40" /></label></details>
      </div>
    </div>
    <div v-else class="emptyComposition"><h3>还没有分镜画格</h3><p>先完成分镜和画面，再来拼页。</p><button @click="emit('draw')">返回漫画制作</button></div>
  </section>
</template>
<script setup lang="ts">
import { computed, watch } from 'vue';
import type { Episode, Panel } from './model';
import type { Files } from './render';
import letteringEditor from './letteringEditor.vue';
const props=defineProps<{episode:Episode;files:Files;previewUrls:string[]}>();
const emit=defineEmits<{draw:[];preview:[];remove:[panel:Panel]}>();
const panelIndex=defineModel<number>("panelIndex",{default:0});
const currentPanel=computed(()=>props.episode.panels[panelIndex.value]);
const pageCount=computed(()=>Math.ceil(props.episode.panels.length/props.episode.layout.perPage));
const pageIndex=computed(()=>Math.floor(panelIndex.value/props.episode.layout.perPage));
type Template={id:string;label:string;count:1|2|4;arrangement:'grid'|'vertical'|'horizontal'};
const templates:Template[]=[{id:'single',label:'单格',count:1,arrangement:'grid'},{id:'vertical',label:'上下双格',count:2,arrangement:'vertical'},{id:'horizontal',label:'左右双格',count:2,arrangement:'horizontal'},{id:'grid',label:'四格',count:4,arrangement:'grid'},{id:'strip',label:'竖向四格',count:4,arrangement:'vertical'}];
function setTemplate(item:Template){props.episode.layout.perPage=item.count;props.episode.layout.arrangement=item.arrangement;}
function move(offset:number){const index=panelIndex.value,next=index+offset;if(!props.episode.panels[next])return;[props.episode.panels[index],props.episode.panels[next]]=[props.episode.panels[next]!,props.episode.panels[index]!];panelIndex.value=next;}
watch(()=>props.episode.panels.length,()=>{panelIndex.value=Math.max(0,Math.min(panelIndex.value,props.episode.panels.length-1));});
</script>
<style scoped>
.compositionWorkspace { display:grid; gap:16px; color:var(--studioInk); }.compositionHeader { display:flex; justify-content:space-between; gap:16px; align-items:center; }.compositionHeader h2 { margin:0; font-size:22px; }.compositionHeader p { margin:7px 0 0; color:var(--studioMuted); font-size:13px; }.compositionHeader > div:last-child { display:flex; gap:8px; }button,select,input,textarea { font:inherit; color:inherit; }button,select { padding:9px 12px; border:1px solid var(--studioLine); border-radius:7px; background:var(--studioCard); }button { cursor:pointer; }button:disabled { opacity:.45; cursor:default; }button[aria-pressed="true"],button.primary { border-color:var(--studioAccent); background:var(--studioAccent); color:white; }button:focus-visible { outline:2px solid var(--studioAccent); outline-offset:3px; }.templateBar { display:flex; align-items:center; flex-wrap:wrap; gap:8px; padding:12px; background:var(--studioCard); border:1px solid var(--studioLine); border-radius:10px; font-size:12px; }.templateBar > button { display:flex; align-items:center; gap:7px; }.miniTemplate { display:grid; gap:2px; width:19px; height:23px; }.miniTemplate i { border:1px solid currentColor; }.horizontal { grid-template-columns:1fr 1fr; }.grid { grid-template-columns:1fr 1fr; }.templateBar details { margin-left:auto; }.templateBar details[open] { width:100%; }.pageOptions { display:grid; grid-template-columns:repeat(auto-fit,minmax(140px,1fr)); gap:16px; padding:16px 0 4px; }.pageOptions label { display:grid; gap:7px; }.compositionBody { display:grid; grid-template-columns:108px minmax(0,1fr); border:1px solid var(--studioLine); border-radius:12px; overflow:hidden; background:var(--studioCard); }.pageNavigator { background:var(--studioPaper); padding:12px 8px; min-width:0; }.pageNavigator label { display:grid; gap:8px; font-size:12px; }.pageNavigator select { padding:8px 4px; width:100%; }.pageButtons { display:grid; gap:10px; max-height:65vh; overflow-y:auto; margin-top:14px; overscroll-behavior:contain; }.pageButtons button { display:grid; gap:7px; padding:7px; font-size:12px; }.pageButtons img { width:100%; aspect-ratio:3/4; object-fit:contain; }.compositionCanvas { min-width:0; padding:16px; background:var(--studioPaper); }.frameToolbar { display:flex; flex-wrap:wrap; align-items:center; gap:8px; margin-bottom:14px; font-size:12px; }.frameToolbar label { display:flex; gap:8px; align-items:center; margin-left:auto; }.frameNotes { padding:14px; margin-top:14px; border:1px solid var(--studioLine); border-radius:8px; background:var(--studioCard); }.frameNotes label { display:grid; gap:8px; margin-top:12px; }.frameNotes textarea,.frameNotes input { padding:10px; background:var(--studioCard); border:1px solid var(--studioLine); border-radius:6px; }summary { cursor:pointer; }.emptyComposition { padding:50px; text-align:center; }@media(max-width:900px){.compositionBody { grid-template-columns:1fr; }.pageButtons { display:none; }.pageNavigator label { display:flex; align-items:center; }.pageNavigator select { width:auto; }.compositionHeader { align-items:start; flex-direction:column; }.compositionCanvas { padding:10px; }}
</style>
